{
  "title": "add-default-timeout-constant",
  "request": "Hey, can we expose a default request timeout in the SDK? I'd like a DEFAULT_TIMEOUT constant (seconds) on the top-level mcp module, set to 30. It'd be handy for callers to reference.",
  "edits": [
    {
      "path": "src/mcp/__init__.py",
      "search": "__all__ = [\"Client\"]",
      "replace": "__all__ = [\"Client\"]\n# default request timeout in seconds\nDEFAULT_TIMEOUT = 30"
    }
  ],
  "test_path": "tests/test_add_default_timeout.py",
  "test": "import importlib\nimport pytest\n\ndef test_default_timeout_exists_and_is_int():\n    mcp = importlib.import_module(\"mcp\")\n    # The attribute should exist after the fix\n    assert hasattr(mcp, \"DEFAULT_TIMEOUT\"), \"DEFAULT_TIMEOUT not defined on mcp module\"\n    assert isinstance(mcp.DEFAULT_TIMEOUT, int)\n    assert mcp.DEFAULT_TIMEOUT == 30\n"
}
